import {guidedRemaining,guidedScore} from './workshop-repair-guided.mjs';
import {repairState} from './workshop-repair-model.mjs';
import {required,snapshot} from './workshop-model.mjs';
export function guidedCoach({g,root,t,fix,reading,testName}){
 const add=(tag,text,parent=root)=>{const e=document.createElement(tag);e.textContent=text;parent.append(e);return e;};
 const card=add('section','');card.id='guidedDecisionCoach';card.className='sequence-coach';
 add('h3',g.phase==='question'?t('¿Qué harías a continuación?','What would you do next?'):g.phase==='feedback'?t('Tu decisión frente a la recomendada','Your decision versus the recommendation'):t('Tu recorrido de práctica','Your practice journey'),card);
 const wrong=g.rounds.filter(r=>!r.useful).length;const score=add('p',t('Puntos: ','Points: ')+guidedScore(g)+'/100 · '+wrong+t(' innecesarias (−15 cada una) · ',' unnecessary (−15 each) · ')+g.hints+t(' pistas (−5 cada una)',' hints (−5 each)'),card);score.setAttribute('role','status');
 add('p',t('Causas corregidas: ','Causes repaired: ')+(g.order.length-guidedRemaining(g).length)+'/'+g.order.length,card);
 if(g.phase==='question'){
  add('p',t('Los dos bancos están en el mismo estado. La reparación recomendada se aplica solo después de elegir. Puedes mover el reloj y medir sin perder puntos.','Both benches are in the same state. The recommended repair is applied only after you choose. You may scrub the clock and measure without losing points.'),card);
  if(g.hinted){const clues={mechanics:['Compara tensión bajo carga y caída en masa. Una caída alta apunta a la conexión; una alimentación baja apunta a la batería.','Compare loaded voltage and ground drop. A high drop points to the connection; low supply points to the battery.'],electronics:['Compara la amplitud de entrada y la ganancia. Su producto no debe superar los rieles; una salida recortada sola no distingue las dos causas.','Compare input amplitude and gain. Their product must stay within the rails; a clipped output alone does not distinguish the two causes.'],hydraulics:['Compara caudal de entrada y fuga. Menor alimentación y fuga interna pueden reducir la velocidad, pero requieren reparaciones distintas.','Compare inlet flow and leakage. Low supply and internal leakage can both reduce speed, but need different repairs.'],pneumatics:['Compara presión de alimentación y contrapresión del escape. Un escape obstruido puede frenar el cilindro aunque tenga alimentación.','Compare supply pressure and exhaust backpressure. A restricted exhaust can slow the cylinder despite an adequate supply.']};add('p',t(...clues[g.user.kind]),card);}
 }else{
  if(g.phase==='feedback'){const r=g.rounds.at(-1);add('p','A · '+fix(g.user,r.recommended)+' / B · '+fix(g.user,r.id),card);add('p',r.useful?t('Tu acción corrigió una causa pendiente. Se aceptan órdenes alternativos útiles.','Your action corrected a remaining cause. Useful alternative orders are accepted.'):t('Tu acción no corrigió una causa pendiente. Mira las diferencias y elige otra intervención en la siguiente decisión.','Your action corrected no remaining cause. Inspect the differences and choose another intervention at the next decision.'),card);}
  for(const time of [.5,1.25]){const table=add('table','',card);table.className='guided-exam-scores';add('caption',t('Comparación al mismo instante: ','Comparison at the same instant: ')+time,table);const tr=add('tr','',add('thead','',table));for(const label of [t('Prueba','Test'),'A','B'])add('th',label,tr).scope='col';const body=add('tbody','',table),a=snapshot({...repairState(g.reference),time}),b=snapshot({...repairState(g.user),time});for(const id of required[g.user.kind]){const row=add('tr','',body),av=reading(a,id),bv=reading(b,id);row.classList.toggle('sequence-difference',av!==bv);add('td',testName(id)+(av!==bv?t(' · Diferencia',' · Difference'):''),row);add('td',av,row);add('td',bv,row);}}
 }
}
